package dev.myjarvis.core;

import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class ScheduleServiceTest extends ReminderTestSupport {
    @Test void inertPreviewConfirmReloadReplaceDisableAndReenable(){
        var preview=preview("CREATE",null,null,definition("DAILY"));for(String table:List.of("schedules","schedule_authorizations","reminder_jobs","notifications"))assertEquals(0,count(table));assertEquals("OWN_INBOX",preview.get("destination"));assertEquals(300,Duration.between(Instant.parse(preview.get("issued_at").toString()),Instant.parse(preview.get("expires_at").toString())).toSeconds());
        UUID id=(UUID)confirm(preview,UUID.randomUUID()).get("schedule_id");assertEquals("ENABLED",schedules.get(session,id).get("status"));var changed=definition("DAILY");changed.put("text","Synthetic replacement");confirm(preview("REPLACE",id,1L,changed),UUID.randomUUID());assertEquals(2L,schedules.get(session,id).get("version"));assertEquals("Synthetic replacement",((tools.jackson.databind.JsonNode)schedules.get(session,id).get("definition")).get("text").asText());
        schedules.disable(session,UUID.randomUUID(),id,body(Map.of("expected_version",2)));assertEquals("DISABLED",schedules.get(session,id).get("status"));assertEquals(3L,schedules.get(session,id).get("version"));assertNull(schedules.get(session,id).get("next_occurrence"));confirm(preview("REPLACE",id,3L,changed),UUID.randomUUID());assertEquals(4L,schedules.get(session,id).get("version"));assertEquals("ENABLED",schedules.get(session,id).get("status"));
    }
    @Test void exactReplayReturnsOnlyOriginalMetadataAndChangedBodyConflicts(){var preview=preview("CREATE",null,null,definition("ONCE"));UUID key=UUID.randomUUID();var first=confirm(preview,key);assertEquals(first,confirm(preview,key));assertEquals(Set.of("status","schedule_id","version","operation"),first.keySet());assertFalse(Json.canonical(first).contains("sentinel"));assertEquals(1,count("schedules"));assertEquals(1,count("schedule_authorizations"));code("APPROVAL_CONSUMED",()->confirm(preview,UUID.randomUUID()));var changed=body(Map.of("expected_preparation_version",1,"payload_hash","0".repeat(64),"confirm",true));code("IDEMPOTENCY_CONFLICT",()->schedules.confirm(session,key,(UUID)preview.get("id"),changed));}
    @Test void rotatedSessionReadsReceiptButCannotReplayOrConsumePreparation(){var saved=preview("CREATE",null,null,definition("ONCE"));var unconsumed=preview("CREATE",null,null,definition("ONCE"));UUID key=UUID.randomUUID();var receipt=confirm(saved,key);var old=session;token=auth.issue(owner,true,session.hash()).token();session=auth.find(token);assertEquals(receipt,schedules.reconcile(session,key));code("MUTATION_SESSION_CHANGED",()->confirm(saved,key));code("MUTATION_SESSION_CHANGED",()->confirm(unconsumed,UUID.randomUUID()));code("SESSION_REVOKED",()->schedules.get(old,(UUID)receipt.get("schedule_id")));}
    @Test void unknownReceiptIsReadOnlyAndInconclusive(){var response=schedules.reconcile(session,UUID.randomUUID());assertEquals("NOT_OBSERVED",response.get("status"));assertNull(response.get("schedule_id"));assertNull(response.get("version"));assertNull(response.get("operation"));assertEquals(0,count("schedule_mutations"));}
    @Test void recentReauthComesFromLiveDatabaseRatherThanSessionObject(){var preview=preview("CREATE",null,null,definition("ONCE"));db.update("UPDATE sessions SET reauthenticated_at=NULL WHERE token_hash=?",session.hash());code("REAUTHENTICATION_REQUIRED",()->confirm(preview,UUID.randomUUID()));db.update("UPDATE sessions SET reauthenticated_at=clock_timestamp()+interval '1 minute' WHERE token_hash=?",session.hash());code("REAUTHENTICATION_REQUIRED",()->confirm(preview,UUID.randomUUID()));db.update("UPDATE sessions SET reauthenticated_at=clock_timestamp()-interval '6 minutes' WHERE token_hash=?",session.hash());code("REAUTHENTICATION_REQUIRED",()->confirm(preview,UUID.randomUUID()));assertEquals(0,count("schedules"));}
    @Test void revokedIdleAndAbsoluteExpiredSessionsCannotActivate(){for(String update:List.of("revoked_at=clock_timestamp()","last_seen_at=clock_timestamp()-interval '3 hours'","created_at=clock_timestamp()-interval '13 hours'")){token=auth.issue(owner,true,null).token();session=auth.find(token);var preview=preview("CREATE",null,null,definition("ONCE"));db.update("UPDATE sessions SET "+update+" WHERE token_hash=?",session.hash());code("SESSION_REVOKED",()->confirm(preview,UUID.randomUUID()));}assertEquals(0,count("schedules"));}
    @Test void previewHashTamperConsumptionAndExpirationFailClosed(){var preview=preview("CREATE",null,null,definition("ONCE"));code("PRECONDITION_CHANGED",()->schedules.confirm(session,UUID.randomUUID(),(UUID)preview.get("id"),body(Map.of("expected_preparation_version",1,"payload_hash","0".repeat(64),"confirm",true))));db.update("UPDATE schedule_preparations SET expires_at=issued_at+interval '1 microsecond',issued_at=issued_at-interval '1 minute' WHERE id=?",preview.get("id"));code("APPROVAL_EXPIRED",()->confirm(preview,UUID.randomUUID()));assertEquals(0,count("schedules"));}
    @Test void passedFirstPreviewRequiresNewReviewInsteadOfSilentRecompute(){var preview=preview("CREATE",null,null,definition("ONCE"));db.update("UPDATE schedule_preparations SET first_fire_at=clock_timestamp()-interval '1 second' WHERE id=?",preview.get("id"));code("APPROVAL_EXPIRED",()->confirm(preview,UUID.randomUUID()));assertEquals(0,count("schedule_authorizations"));}
    @Test void strictDefinitionRejectsAuthorityFieldsControlsOffsetsAndInconsistentDays(){
        for(String extra:List.of("owner_id","status","verified","grant_id","tool_id","provider","callback")){var definition=definition("ONCE");definition.put(extra,"forbidden");code("INVALID_REQUEST",()->preview("CREATE",null,null,definition));}
        for(String text:List.of(""," ","\u00a0","line\n","control\u0085","\ud800","x".repeat(2001))){var definition=definition("ONCE");definition.put("text",text);code("INVALID_REQUEST",()->preview("CREATE",null,null,definition));}
        for(String zone:List.of("+09:00","GMT+09:00","CST","Asia/seoul","SystemV/EST5EDT")){var definition=definition("ONCE");definition.put("timezone",zone);code("INVALID_TIMEZONE",()->preview("CREATE",null,null,definition));}
        for(Object days:List.of(List.of(2,1),List.of(1,1),List.of(0),List.of(true),List.of(8),List.of(4294967297L))){var definition=definition("CUSTOM_DAYS");definition.put("weekdays",days);code("INVALID_REQUEST",()->preview("CREATE",null,null,definition));}
        for(Object max:List.of(0,32,true,1.5,9007199254740992L)){var definition=definition("DAILY");definition.put("max_deliveries",max);code("INVALID_REQUEST",()->preview("CREATE",null,null,definition));}
    }
    @Test void expiryBoundsEmptyRecurrenceAndTimestampPrecisionAreStrict(){
        for(String expiry:List.of("2030-01-01T00:00:00+00:00","2030-01-01t00:00:00z","2030-02-30T00:00:00Z","2030-01-01T00:00:60Z","2030-01-01T00:00:00.1234567Z",schedules.databaseNow().plusSeconds(31*86400).toString(),schedules.databaseNow().minusSeconds(1).toString())){var definition=definition("ONCE");definition.put("authorization_expires_at",expiry);code("INVALID_REQUEST",()->preview("CREATE",null,null,definition));}
        var definition=definition("ONCE");definition.put("start_date","0001-01-01");code("INVALID_REQUEST",()->preview("CREATE",null,null,definition));
    }
    @Test void confirmationCreatesOnlyNarrowInboxAuthority(){create("DAILY");for(String table:List.of("authorizations","jobs","runs","action_proposals","task_user_intents","memory_write_intents","inference_reservations")){assertEquals(0,count(table));}var authority=db.queryForMap("SELECT * FROM schedule_authorizations");assertEquals("inbox.reminder.create",authority.get("action"));assertEquals(owner,authority.get("recipient_owner_id"));assertEquals(0,authority.get("delivered_count"));assertEquals(31,authority.get("max_deliveries"));for(int i=1;i<100;i++)create("ONCE");var extra=preview("CREATE",null,null,definition("ONCE"));code("SCHEDULE_LIMIT_REACHED",()->confirm(extra,UUID.randomUUID()));assertEquals(100,count("schedules"));assertEquals(100,count("schedule_authorizations"));assertNull(db.queryForObject("SELECT consumed_at FROM schedule_preparations WHERE id=?",Object.class,extra.get("id")));}
    @Test void disabledWhilePausedWithoutReauthAndResumeDoesNotReauthorize(){UUID id=create("DAILY");flow.pause(session,true);session=auth.find(token);db.update("UPDATE sessions SET reauthenticated_at=NULL WHERE token_hash=?",session.hash());assertEquals("RECONFIRM_REQUIRED",schedules.get(session,id).get("status"));var receipt=schedules.disable(session,UUID.randomUUID(),id,body(Map.of("expected_version",1)));assertEquals("DISABLE",receipt.get("operation"));assertEquals("DISABLED",schedules.get(session,id).get("status"));}
    @Test void encryptedRowsAndPurposeBindingsHideContentFromMetadata(){UUID id=create("ONCE");for(String table:List.of("schedules","schedule_preparations","schedule_authorizations","schedule_mutations","audit_events")){String dump=Json.canonical(db.queryForList("SELECT * FROM "+table));assertFalse(dump.contains("sentinel"));assertFalse(dump.contains("Synthetic private"));}String encrypted=db.queryForObject("SELECT definition_ref FROM schedules WHERE id=?",String.class,id);assertThrows(Exception.class,()->vault.open(UUID.randomUUID(),id,"schedule-definition:1",encrypted));assertThrows(Exception.class,()->vault.open(owner,UUID.randomUUID(),"schedule-definition:1",encrypted));assertThrows(Exception.class,()->vault.open(owner,id,"schedule-preparation",encrypted));var preparation=db.queryForMap("SELECT id,snapshot_ref FROM schedule_preparations");assertThrows(Exception.class,()->vault.open(owner,(UUID)preparation.get("id"),"schedule-definition:1",(String)preparation.get("snapshot_ref")));}
    @Test void auditFailureRollsBackActivationAndPreparationConsumption(){var preview=preview("CREATE",null,null,definition("ONCE"));db.execute("ALTER TABLE audit_events ADD CONSTRAINT reminder_audit_failure CHECK(event_type<>'SCHEDULE_CREATE_CONFIRMED')");try{assertThrows(Exception.class,()->confirm(preview,UUID.randomUUID()));assertEquals(0,count("schedules"));assertEquals(0,count("schedule_authorizations"));assertEquals(0,count("schedule_mutations"));assertNull(db.queryForObject("SELECT consumed_at FROM schedule_preparations WHERE id=?",Object.class,preview.get("id")));}finally{db.execute("ALTER TABLE audit_events DROP CONSTRAINT reminder_audit_failure");}}
    @Test void restartRetainsDefinitionAndMetadataReceipt(){var preview=preview("CREATE",null,null,definition("ONCE"));UUID key=UUID.randomUUID();var receipt=confirm(preview,key);context.close();open();assertEquals(receipt,schedules.reconcile(session,key));assertEquals("ENABLED",schedules.get(session,(UUID)receipt.get("schedule_id")).get("status"));}
    @Test void parallelConfirmationConsumesPreparationOnce() throws Exception{var preview=preview("CREATE",null,null,definition("ONCE"));try(var pool=Executors.newFixedThreadPool(2)){List<Callable<Boolean>> work=List.of(()->{try{confirm(preview,UUID.randomUUID());return true;}catch(ApiException e){assertEquals("APPROVAL_CONSUMED",e.code);return false;}},()->{try{confirm(preview,UUID.randomUUID());return true;}catch(ApiException e){assertEquals("APPROVAL_CONSUMED",e.code);return false;}});int wins=0;for(var future:pool.invokeAll(work,30,TimeUnit.SECONDS)){assertFalse(future.isCancelled());if(future.get())wins++;}assertEquals(1,wins);}assertEquals(1,count("schedules"));assertEquals(1,count("schedule_authorizations"));}
    @Test void parallelReplacementsAtOneVersionHaveOneWinner() throws Exception{UUID id=create("DAILY");var first=preview("REPLACE",id,1L,definition("DAILY"));var second=preview("REPLACE",id,1L,definition("DAILY"));try(var pool=Executors.newFixedThreadPool(2)){List<Callable<Boolean>> work=new ArrayList<>();for(var preview:List.of(first,second))work.add(()->{try{confirm(preview,UUID.randomUUID());return true;}catch(ScheduleService.ScheduleConflict e){assertEquals(2,e.currentVersion);return false;}});int wins=0;for(var future:pool.invokeAll(work,30,TimeUnit.SECONDS)){assertFalse(future.isCancelled());if(future.get())wins++;}assertEquals(1,wins);}assertEquals(2L,schedules.get(session,id).get("version"));}
    @Test void ownerLockSerializesLogoutBeforeConfirmation() throws Exception{var preview=preview("CREATE",null,null,definition("ONCE"));var current=session;CountDownLatch entered=new CountDownLatch(1);try(var pool=Executors.newSingleThreadExecutor()){var pending=new java.util.concurrent.atomic.AtomicReference<Future<String>>();schedules.writeTx.executeWithoutResult(tx->{schedules.lockOwner(owner);pending.set(pool.submit(()->{entered.countDown();try{schedules.confirm(current,UUID.randomUUID(),(UUID)preview.get("id"),confirmation(preview));return "COMMITTED";}catch(ApiException e){return e.code;}}));try{assertTrue(entered.await(5,TimeUnit.SECONDS));}catch(InterruptedException e){throw new IllegalStateException(e);}auth.logout(current);});assertEquals("SESSION_REVOKED",pending.get().get(15,TimeUnit.SECONDS));}assertEquals(0,count("schedules"));}
    @Test void foreignIdsAndCursorContextsNeverReturnPrivateRecords(){UUID id=create("ONCE");code("NOT_FOUND",()->schedules.get(session,UUID.randomUUID()));code("NOT_FOUND",()->schedules.occurrences(session,UUID.randomUUID(),null,20));var definition=definition("ONCE");definition.put("project_id",UUID.randomUUID());code("NOT_FOUND",()->preview("CREATE",null,null,definition));String cursor=schedules.keys.cursor(UUID.randomUUID(),"schedules|null",schedules.databaseNow()+"|"+id);code("NOT_FOUND",()->schedules.list(session,null,cursor,20));String wrongScope=schedules.keys.cursor(owner,"notifications|null",schedules.databaseNow()+"|"+id);code("NOT_FOUND",()->schedules.list(session,null,wrongScope,20));}
    @Test void versionCapFailsWithoutRevokingAuthority(){UUID id=create("ONCE");db.update("UPDATE schedules SET version=? WHERE id=?",ScheduleService.MAX,id);code("VERSION_EXHAUSTED",()->preview("REPLACE",id,ScheduleService.MAX,definition("ONCE")));code("VERSION_EXHAUSTED",()->schedules.disable(session,UUID.randomUUID(),id,body(Map.of("expected_version",ScheduleService.MAX))));assertNull(db.queryForObject("SELECT revoked_at FROM schedule_authorizations WHERE schedule_id=?",Object.class,id));}
    @Test void jvmClockSkewCannotChangeDatabasePreviewOrSessionValidity(){Instant lower=schedules.databaseNow();try(var mocked=org.mockito.Mockito.mockStatic(Instant.class,org.mockito.Mockito.CALLS_REAL_METHODS)){mocked.when(Instant::now).thenReturn(lower.plusSeconds(86400));var preview=preview("CREATE",null,null,definition("ONCE"));Instant issued=Instant.parse(preview.get("issued_at").toString());assertFalse(issued.isBefore(lower));assertTrue(Duration.between(lower,issued).toSeconds()<30);confirm(preview,UUID.randomUUID());}assertEquals(1,count("schedules"));}
    @Test void sharedDefinitionFixturesAgreeWithServerValidation() throws Exception {
        // Parse the fixture container without strict-number validation: individual invalid cases intentionally contain unsafe values.
        var fixtures=Json.MAPPER.readTree(java.nio.file.Files.readString(java.nio.file.Path.of("../../packages/contracts/fixtures/schedules-inbox/cases.json")));
        for(var fixture:fixtures){if(!fixture.get("schema").asText().equals("schedule-definition"))continue;if(fixture.get("valid").asBoolean())assertDoesNotThrow(()->schedules.definition(fixture.get("instance")),fixture.get("name").asText());else assertThrows(ApiException.class,()->schedules.definition(fixture.get("instance")),fixture.get("name").asText());}
    }
    @Test void immutablePreparationMetadataMustMatchEncryptedPreview(){
        for(String field:List.of("target_id","first_fire_at","issued_at","expected_version")){
            var preview=preview("CREATE",null,null,definition("ONCE"));UUID id=(UUID)preview.get("id");
            if(field.equals("target_id"))db.update("UPDATE schedule_preparations SET target_id=? WHERE id=?",UUID.randomUUID(),id);
            else if(field.equals("expected_version"))db.update("UPDATE schedule_preparations SET operation='REPLACE',expected_version=1 WHERE id=?",id);
            else db.update("UPDATE schedule_preparations SET "+field+"="+field+"+interval '1 second' WHERE id=?",id);
            code("PRECONDITION_CHANGED",()->confirm(preview,UUID.randomUUID()));
        }
        assertEquals(0,count("schedules"));assertEquals(0,count("schedule_authorizations"));
    }
}
